package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/logging"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

type persistentRefBuilder func() (newHash, expectedHash plumbing.Hash, err error)

func repositoryDirs(ctx context.Context, repo *git.Repository) (worktreeRoot, commonDir string, err error) {
	wt, err := repo.Worktree()
	if err != nil {
		return "", "", fmt.Errorf("open worktree: %w", err)
	}
	worktreeRoot = wt.Filesystem().Root()
	if worktreeRoot == "" {
		return "", "", errors.New("repository worktree filesystem has no root path")
	}
	commonDir, err = resolveGitCommonDir(ctx, repo)
	if err != nil {
		return "", "", err
	}
	return worktreeRoot, commonDir, nil
}

// casUpdateRef atomically updates refName through native Git's lock protocol.
// Pass ZeroHash as expectedHash to require that the ref does not exist.
func casUpdateRef(ctx context.Context, repoRoot string, refName plumbing.ReferenceName, newHash, expectedHash plumbing.Hash) error {
	newValue := newHash.String()
	oldValue := strings.Repeat("0", newHash.HexSize())
	if expectedHash != plumbing.ZeroHash {
		oldValue = expectedHash.String()
	}

	cmd := exec.CommandContext(ctx, "git", "update-ref", refName.String(), newValue, oldValue)
	cmd.Dir = repoRoot
	cmd.Env = append(os.Environ(), "LC_ALL=C", "LANG=C")
	output, err := cmd.CombinedOutput()
	if err == nil {
		return nil
	}

	out := string(output)
	if strings.Contains(out, "cannot lock ref") || strings.Contains(out, "but expected") {
		return ErrShadowRefBusy
	}
	return fmt.Errorf("git update-ref %s: %s: %w", refName, strings.TrimSpace(out), err)
}

func persistentRefLockPath(commonDir string, refName plumbing.ReferenceName) (string, error) {
	lockDir := filepath.Join(commonDir, "entire-persistent-ref-locks")
	if err := os.MkdirAll(lockDir, 0o750); err != nil {
		return "", fmt.Errorf("create persistent ref lock directory: %w", err)
	}
	safe := strings.NewReplacer("/", "_", "\\", "_", ":", "_").Replace(refName.String())
	return filepath.Join(lockDir, safe+".lock"), nil
}

func withPersistentRefFlock(ctx context.Context, commonDir string, refName plumbing.ReferenceName, fn func() error) error {
	path, err := persistentRefLockPath(commonDir, refName)
	if err != nil {
		return err
	}
	release, err := flock.AcquireContext(ctx, path)
	if err != nil {
		return fmt.Errorf("acquire persistent ref flock %s: %w", refName, err)
	}
	defer release()
	return fn()
}

// updatePersistentRef serializes Entire writers for one ref and retains a CAS
// retry for native Git or other external writers. build runs again after every
// conflict, so each retry reconstructs its tree and commit from the fresh tip.
func updatePersistentRef(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, build persistentRefBuilder) error {
	repoRoot, commonDir, err := repositoryDirs(ctx, repo)
	if err != nil {
		return fmt.Errorf("resolve repository directories: %w", err)
	}

	return withPersistentRefFlock(ctx, commonDir, refName, func() error {
		for attempt := range shadowRefMaxRetries {
			newHash, expectedHash, buildErr := build()
			if buildErr != nil {
				return buildErr
			}

			refErr := casUpdateRef(ctx, repoRoot, refName, newHash, expectedHash)
			if refErr == nil {
				return nil
			}
			if !errors.Is(refErr, ErrShadowRefBusy) {
				return fmt.Errorf("update persistent ref %s: %w", refName, refErr)
			}
			if newHash != expectedHash {
				tryDeleteLooseObject(commonDir, newHash)
			}

			if backoffErr := shadowRefBackoff(ctx, attempt); backoffErr != nil {
				return backoffErr
			}
		}

		logging.Warn(logging.WithComponent(ctx, "checkpoint"),
			"persistent ref CAS retry budget exhausted",
			slog.String("ref", refName.String()),
			slog.Int("retries", shadowRefMaxRetries),
		)
		return fmt.Errorf("failed to update persistent ref %s after %d CAS retries: %w", refName, shadowRefMaxRetries, ErrShadowRefBusy)
	})
}
package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"os"
	"os/exec"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

// ErrRefConflict identifies a native Git compare-and-swap failure.
var ErrRefConflict = errors.New("git ref moved during update")

// ErrRefMoveConflict identifies a failed source/destination ref move.
var ErrRefMoveConflict = errors.New("git ref move conflict")

const (
	refTransactionMaxAttempts = 16
	refTransactionMaxJitter   = 8 * time.Millisecond
)

// repositoryObjectLocks protects go-git's repository-local filesystem object
// cache. Native Git CAS remains the cross-process ref-publication boundary.
var repositoryObjectLocks sync.Map

func repositoryObjectLock(repo *git.Repository) *sync.Mutex {
	lock, _ := repositoryObjectLocks.LoadOrStore(repo, &sync.Mutex{})
	objectLock, ok := lock.(*sync.Mutex)
	if !ok {
		panic("checkpoint repository object lock has an unexpected type")
	}
	return objectLock
}

// RefConflictError reports the expected and observed tips for a failed ref CAS.
type RefConflictError struct {
	Ref      plumbing.ReferenceName
	Expected plumbing.Hash
	Actual   plumbing.Hash
}

// RefMoveConflictError reports a source or destination change that prevented
// an atomic ref move.
type RefMoveConflictError struct {
	Source            plumbing.ReferenceName
	Destination       plumbing.ReferenceName
	ExpectedSource    plumbing.Hash
	ActualSource      plumbing.Hash
	ActualDestination plumbing.Hash
}

func (e *RefMoveConflictError) Error() string {
	return fmt.Sprintf("move %s to %s: %v (source expected %s, found %s; destination found %s)",
		e.Source, e.Destination, ErrRefMoveConflict, e.ExpectedSource, e.ActualSource, e.ActualDestination)
}

func (e *RefMoveConflictError) Unwrap() error {
	return ErrRefMoveConflict
}

func (e *RefConflictError) Error() string {
	return fmt.Sprintf("%s: %v (expected %s, found %s)", e.Ref, ErrRefConflict, e.Expected, e.Actual)
}

func (e *RefConflictError) Unwrap() error {
	return ErrRefConflict
}

// RefMutation rebuilds a ref update from its current tip. changed=false is an
// idempotent no-op and returns current without invoking git update-ref.
type RefMutation func(current plumbing.Hash) (next plumbing.Hash, changed bool, err error)

// RefUpdate describes one compare-and-swap in a multi-ref transaction.
type RefUpdate struct {
	Ref      plumbing.ReferenceName
	New      plumbing.Hash
	Expected plumbing.Hash
}

// MultiRefMutation rebuilds a set of ref updates from their current tips.
// changed=false is an idempotent no-op.
type MultiRefMutation func(current map[plumbing.ReferenceName]plumbing.Hash) (next map[plumbing.ReferenceName]plumbing.Hash, changed bool, err error)

type beforeRefCASKey struct{}

func withBeforeRefCAS(ctx context.Context, hook func()) context.Context {
	return context.WithValue(ctx, beforeRefCASKey{}, hook)
}

// RunRefTransaction retries a logical ref mutation against the latest tip.
// The callback is invoked again after every CAS conflict, so it must rebuild
// trees and commits from current rather than reuse objects based on a stale tip.
func RunRefTransaction(
	ctx context.Context,
	repo *git.Repository,
	refName plumbing.ReferenceName,
	mutate RefMutation,
) (plumbing.Hash, error) {
	for attempt := range refTransactionMaxAttempts {
		if err := ctx.Err(); err != nil {
