// even during shutdown (a second Ctrl-C still force-quits the process).
func (s *gitRefsStore) enqueueForPush(ctx context.Context, refName plumbing.ReferenceName) {
	q, err := PushQueueForRepo(context.WithoutCancel(ctx), s.repo)
	if err != nil {
		logging.Warn(ctx, "checkpoint: resolve push queue failed; ref not enqueued",
			slog.String("ref", refName.String()), slog.String("error", err.Error()))
		return
	}
	if err := q.Enqueue(refName); err != nil {
		logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
			slog.String("ref", refName.String()), slog.String("error", err.Error()))
	}
}

func (s *gitRefsStore) backfillTranscript(ctx context.Context, opts UpdateOptions) error {
	if err := ctx.Err(); err != nil {
		return err //nolint:wrapcheck // Propagating context cancellation
	}
	if opts.CheckpointID.IsEmpty() {
		return errors.New("invalid update options: checkpoint ID is required")
	}

	refName, err := s.prepareRefForBackfill(ctx, opts.CheckpointID)
	if err != nil {
		return err
	}
	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Finalize transcript for Checkpoint: %s", opts.CheckpointID)
	_, err = RunRefTransaction(ctx, s.repo, refName, func(parentHash plumbing.Hash) (plumbing.Hash, bool, error) {
		existing, err := s.checkpointTreeAt(parentHash, opts.CheckpointID)
		if err != nil {
			return plumbing.ZeroHash, false, err
		}
		checkpointSubtree, err := s.applyTranscriptBackfill(ctx, opts, existing, "")
		if err != nil {
			return plumbing.ZeroHash, false, err
		}
		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
		return commitHash, true, err
	})
	if err != nil {
		return err
	}
	s.enqueueForPush(ctx, refName)
	return nil
}

func (s *gitRefsStore) backfillSummary(ctx context.Context, req SessionSummary) error {
	if err := ctx.Err(); err != nil {
		return err //nolint:wrapcheck // Propagating context cancellation
	}

	refName, err := s.prepareRefForBackfill(ctx, req.CheckpointID)
	if err != nil {
		return err
	}
	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	targetSessionID := req.SessionID
	_, err = RunRefTransaction(ctx, s.repo, refName, func(parentHash plumbing.Hash) (plumbing.Hash, bool, error) {
		existing, err := s.checkpointTreeAt(parentHash, req.CheckpointID)
		if err != nil {
			return plumbing.ZeroHash, false, err
		}
		checkpointSubtree, sessionID, err := s.applySummaryBackfill(ctx, existing, "", targetSessionID, req.Summary)
		if err != nil {
			return plumbing.ZeroHash, false, err
		}
		if targetSessionID == "" {
			targetSessionID = sessionID
		}
		commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", req.CheckpointID, sessionID)
		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
		return commitHash, true, err
	})
	if err != nil {
		return err
	}
	s.enqueueForPush(ctx, refName)
	return nil
}

func (s *gitRefsStore) backfillAttribution(ctx context.Context, checkpointID id.CheckpointID, combinedAttribution *Attribution) error {
	if err := ctx.Err(); err != nil {
		return err //nolint:wrapcheck // Propagating context cancellation
	}

	refName, err := s.prepareRefForBackfill(ctx, checkpointID)
	if err != nil {
		return err
	}
	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Update checkpoint summary for %s", checkpointID)
	_, err = RunRefTransaction(ctx, s.repo, refName, func(parentHash plumbing.Hash) (plumbing.Hash, bool, error) {
		existing, err := s.checkpointTreeAt(parentHash, checkpointID)
		if err != nil {
			return plumbing.ZeroHash, false, err
		}
		checkpointSubtree, err := s.applyAttributionBackfill(ctx, existing, "", combinedAttribution)
		if err != nil {
			return plumbing.ZeroHash, false, err
		}
		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
		return commitHash, true, err
	})
	if err != nil {
		return err
	}
	s.enqueueForPush(ctx, refName)
	return nil
}

func (s *gitRefsStore) prepareRefForBackfill(ctx context.Context, checkpointID id.CheckpointID) (plumbing.ReferenceName, error) {
	refName, err := RefName(checkpointID)
	if err != nil {
		return "", err
	}
	if _, err := s.resolveRefMaybeFetch(ctx, checkpointID); err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return "", ErrCheckpointNotFound
		}
		return "", err
	rootTreeHash, err := s.rootTreeHashAt(parentHash)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	existing, err := s.subtreeObjAt(rootTreeHash, checkpointID.Path())
	if err != nil {
		return plumbing.ZeroHash, err
	}
	checkpointSubtree, err := s.applyAttributionBackfill(ctx, existing, checkpointID.Path()+"/", attribution)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, checkpointID, checkpointSubtree)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	return CreateCommit(ctx, s.repo, newTreeHash, parentHash, fmt.Sprintf("Update checkpoint summary for %s", checkpointID), authorName, authorEmail)
}

func (s *gitRefsStore) buildPreparedAttributionCommit(ctx context.Context, checkpointID id.CheckpointID, attribution *Attribution, parentHash plumbing.Hash, authorName, authorEmail string) (plumbing.Hash, error) {
	existing, err := s.checkpointTreeAt(parentHash, checkpointID)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	checkpointSubtree, err := s.applyAttributionBackfill(ctx, existing, "", attribution)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	return CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, fmt.Sprintf("Update checkpoint summary for %s", checkpointID), authorName, authorEmail)
}

func writePreparedBatch(ctx context.Context, writer batchRefWriter, prepared *preparedBatchSessions) error {
	refName, err := writer.batchRefName(prepared.request.CheckpointID)
	if err != nil {
		return err
	}
	if err := writer.prepareBatchRef(ctx); err != nil {
		return err
	}
	_, err = RunRefTransaction(ctx, writer.batchRepo(), refName, func(parentHash plumbing.Hash) (plumbing.Hash, bool, error) {
		commitHash, err := writer.buildPreparedBatchCommit(ctx, prepared, parentHash)
		return commitHash, true, err
	})
	if err != nil {
		return err
	}
	writer.afterBatchPublish(ctx, refName)
	return nil
}

func (s *treeWriter) applyPreparedBatch(
	ctx context.Context,
	prepared *preparedBatchSessions,
	existing *object.Tree,
	basePath string,
) (plumbing.Hash, batchBuildStats, error) {
	var stats batchBuildStats
	if err := ctx.Err(); err != nil {
		return plumbing.ZeroHash, stats, err //nolint:wrapcheck // Propagating context cancellation
	}

	rootEntries := make(map[string]object.TreeEntry)
	if existing != nil {
		for _, entry := range existing.Entries {
			stats.RootEntriesVisited++
			rootEntries[entry.Name] = entry
		}
	}

	var existingSummary *CheckpointSummary
	if entry, ok := rootEntries[paths.MetadataFileName]; ok {
		var err error
		existingSummary, err = s.readSummaryFromBlob(entry.Hash)
		if err != nil {
			return plumbing.ZeroHash, stats, fmt.Errorf("read existing checkpoint summary: %w", err)
		}
		if existingSummary.CheckpointID != prepared.request.CheckpointID {
			return plumbing.ZeroHash, stats, fmt.Errorf("existing checkpoint summary ID %s does not match batch checkpoint ID %s", existingSummary.CheckpointID, prepared.request.CheckpointID)
		}
	} else if existing != nil && len(existing.Entries) != 0 {
		return plumbing.ZeroHash, stats, errors.New("existing checkpoint tree has no root metadata")
	}

	var sessionPaths []SessionFilePaths
	finalByID := make(map[string]finalBatchSession)
	indexBySession := make(map[string]int)
		Imported:            imported,
	}

	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
	}
	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return err
	}
	entries[rootMetadataPath] = object.TreeEntry{
		Name: rootMetadataPath,
		Mode: filemode.Regular,
		Hash: metadataHash,
	}
	return nil
}

// backfillAttribution updates root-level checkpoint metadata fields that depend
// on the full set of sessions already written to the checkpoint.
