func (s *GitStore) backfillAttribution(ctx context.Context, checkpointID id.CheckpointID, combinedAttribution *Attribution) error {
	if err := ctx.Err(); err != nil {
		return err //nolint:wrapcheck // Propagating context cancellation
	}

	// Backfills require the branch to exist; a miss must not create it.
	if err := s.requireSessionsBranch(); err != nil {
		return err
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Update checkpoint summary for %s", checkpointID)
	_, err := RunRefTransaction(ctx, s.repo, s.refs.Primary, func(parentHash plumbing.Hash) (plumbing.Hash, bool, error) {
		if parentHash.IsZero() {
			return plumbing.ZeroHash, false, ErrCheckpointNotFound
		}
		rootTreeHash, err := s.rootTreeHashAt(parentHash)
		if err != nil {
			return plumbing.ZeroHash, false, err
		}
		existing, err := s.subtreeObjAt(rootTreeHash, checkpointID.Path())
		if err != nil {
			return plumbing.ZeroHash, false, err
		}
		checkpointSubtree, err := s.applyAttributionBackfill(ctx, existing, checkpointID.Path()+"/", combinedAttribution)
		if err != nil {
			return plumbing.ZeroHash, false, err
		}
		newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, checkpointID, checkpointSubtree)
		if err != nil {
			return plumbing.ZeroHash, false, err
		}
		newCommitHash, err := CreateCommit(ctx, s.repo, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
		return newCommitHash, true, err
	})
	return err
}

// findSessionIndex returns the index of an existing session with the given ID,
// or the next available index if not found. This prevents duplicate session entries.
	assert.Nil(t, summary)
}

// TestGitRefsStore_WriteRefusesCanceledContext pins that a canceled context
// stops the refs store from minting checkpoints — see writeSession for why.
func TestGitRefsStore_WriteRefusesCanceledContext(t *testing.T) {
	t.Parallel()
	store := newRefsStore(t)
	cid := id.MustCheckpointID("a1b2c3d4e5f6")

	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	err := store.Write(ctx, Session{
		CheckpointID: cid,
		SessionID:    "sess-1",
		Strategy:     "manual-commit",
		Transcript:   redact.AlreadyRedacted([]byte("transcript")),
		AuthorName:   "Test Author",
		AuthorEmail:  "test@example.com",
	})
	require.ErrorIs(t, err, context.Canceled)

	_, refErr := store.repo.Reference(mustRefName(t, cid), true)
	assert.ErrorIs(t, refErr, plumbing.ErrReferenceNotFound,
		"a write refused for cancellation must not leave a checkpoint ref behind")
}

// TestGitRefsStore_EnqueuesAfterCancellationFollowingCAS pins that cancellation
// after a successful ref update does not drop the push-queue record.
func TestGitRefsStore_EnqueuesAfterCancellationFollowingCAS(t *testing.T) {
	t.Parallel()
	store := newRefsStore(t)
	cid := id.MustCheckpointID("a1b2c3d4e5f6")
	refName := mustRefName(t, cid)

	head, err := store.repo.Head()
	require.NoError(t, err)

	ctx, cancel := context.WithCancel(context.Background())
	require.NoError(t, CompareAndSwapRef(context.Background(), store.repo, refName, head.Hash(), plumbing.ZeroHash))
	cancel()
	store.enqueueForPush(ctx, refName)

	q, err := PushQueueForRepo(context.Background(), store.repo)
	require.NoError(t, err)
	refs, err := q.Drain()
	require.NoError(t, err)
	assert.Contains(t, refs, refName,
		"a successful CAS must still be queued when cancellation follows it")
}

