package flock

import (
	"context"
	"errors"
	"fmt"
	"os"
	"time"

	"golang.org/x/sys/windows"
)

// pollInterval is how often the bounded AcquireContext path retries a
// non-blocking lock while waiting for a deadline.
const pollInterval = 25 * time.Millisecond

// Acquire takes an exclusive lock on path via Windows LockFileEx. The
// returned release unlocks and closes the file. Callers must invoke release
// exactly once. Acquire blocks indefinitely until the lock is available; use
// AcquireContext with a deadline to bound the wait.
func Acquire(path string) (release func(), err error) {
	return AcquireContext(context.Background(), path)
}

// AcquireContext behaves like Acquire but honors ctx. When ctx carries a
// deadline it polls a fail-immediately lock until acquired or the deadline
// fires; otherwise it blocks like Acquire. See the unix implementation for the
// rationale.
func AcquireContext(ctx context.Context, path string) (release func(), err error) {
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600) //nolint:gosec // caller is responsible for path validation
	if err != nil {
		return nil, fmt.Errorf("open flock: %w", err)
	}
	overlapped := new(windows.Overlapped)
	releaseFn := func() {
		_ = windows.UnlockFileEx(windows.Handle(f.Fd()), 0, 1, 0, overlapped)
		_ = f.Close()
	}

	if _, hasDeadline := ctx.Deadline(); !hasDeadline {
		if err := windows.LockFileEx(windows.Handle(f.Fd()), windows.LOCKFILE_EXCLUSIVE_LOCK, 0, 1, 0, overlapped); err != nil {
			_ = f.Close()
			return nil, fmt.Errorf("lock flock: %w", err)
		}
		return releaseFn, nil
	}

	for {
		lockErr := windows.LockFileEx(windows.Handle(f.Fd()),
			windows.LOCKFILE_EXCLUSIVE_LOCK|windows.LOCKFILE_FAIL_IMMEDIATELY, 0, 1, 0, overlapped)
		if lockErr == nil {
			return releaseFn, nil
		}
		// Only lock contention is retryable. LOCKFILE_FAIL_IMMEDIATELY reports a
		// held lock as ERROR_LOCK_VIOLATION (or ERROR_IO_PENDING); any other error
		// is a genuine failure (I/O, bad handle) that must fail fast rather than
		// polling until the deadline and masking the real cause as a timeout —
		// mirroring the unix path, which only retries on EWOULDBLOCK.
		if !errors.Is(lockErr, windows.ERROR_LOCK_VIOLATION) && !errors.Is(lockErr, windows.ERROR_IO_PENDING) {
			_ = f.Close()
			return nil, fmt.Errorf("lock flock: %w", lockErr)
		}
		if err := ctx.Err(); err != nil {
			_ = f.Close()
			return nil, fmt.Errorf("lock flock: %w", err)
		}
		select {
		case <-ctx.Done():
			_ = f.Close()
			return nil, fmt.Errorf("lock flock: %w", ctx.Err())
		case <-time.After(pollInterval):
		}
	}
}

package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"

	"github.com/go-git/go-git/v6"
)

// commonDirCache memoizes resolved git common dirs by worktree root. The value
// cannot change for a worktree's lifetime, and resolving it costs a git
// subprocess (~10ms) — which the push-discovery queue pays on EVERY checkpoint
// ref write and the ephemeral store pays on every shadow-branch write, i.e.
// once per agent turn on the hook path and once per turn imported by `entire
// import`. Mirrors session.getGitCommonDir, which already caches this same
// value process-wide for its own callers.
//
// Only successes are cached: a failure may be transient (a canceled context
// fails the subprocess instantly), and caching it would poison every later
// caller in the process.
var (
	commonDirMu    sync.RWMutex
	commonDirCache = map[string]string{} // worktree root -> resolved common dir
)

// cachedCommonDir returns the memoized common dir for a worktree root.
func cachedCommonDir(root string) (string, bool) {
	commonDirMu.RLock()
	defer commonDirMu.RUnlock()
	dir, ok := commonDirCache[root]
	return dir, ok
}

func resolveGitCommonDir(ctx context.Context, repo *git.Repository) (string, error) {
	worktree, err := repo.Worktree()
	if err != nil {
		return "", fmt.Errorf("open worktree for git common dir: %w", err)
	}
	root := worktree.Filesystem().Root()
	if root == "" {
		return "", errors.New("resolve worktree root for git common dir")
	}
	if cached, ok := cachedCommonDir(root); ok {
		return cached, nil
	}

	cmd := exec.CommandContext(ctx, "git", "-C", root, "rev-parse", "--git-common-dir")
	// Use Output (not CombinedOutput) so stderr never pollutes the resolved
	// path on success. Output populates ExitError.Stderr when cmd.Stderr is
	// nil, so error detail is still available without merging streams.
	output, err := cmd.Output()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			if detail := strings.TrimSpace(string(exitErr.Stderr)); detail != "" {
				return "", fmt.Errorf("resolve git common dir: %w: %s", err, detail)
			}
		}
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}
	commonDir := strings.TrimSpace(string(output))
	if commonDir == "" {
		return "", errors.New("resolve git common dir: empty output")
	}
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(root, commonDir)
	}
	commonDir = filepath.Clean(commonDir)
	commonDirMu.Lock()
	commonDirCache[root] = commonDir
	commonDirMu.Unlock()
	return commonDir, nil
}
