func (s *GitStore) ensureSessionsBranch(ctx context.Context) error {
	_, err := RunRefTransaction(ctx, s.repo, s.refs.Primary, func(current plumbing.Hash) (plumbing.Hash, bool, error) {
		if !current.IsZero() {
