func TestRunPersistentRefTransactions_RebuildsAndCleansLosingCommits(t *testing.T) {
	t.Parallel()
	repo, initial := setupBranchTestRepo(t)
	first := plumbing.ReferenceName("refs/entire/checkpoints/01/first-cleanup")
	second := plumbing.ReferenceName("refs/entire/checkpoints/01/second-cleanup")
	if err := CompareAndSwapRefs(t.Context(), repo, []RefUpdate{
		{Ref: first, New: initial, Expected: plumbing.ZeroHash},
		{Ref: second, New: initial, Expected: plumbing.ZeroHash},
	}); err != nil {
		t.Fatalf("initialize refs: %v", err)
	}
	initialCommit, err := repo.CommitObject(initial)
	if err != nil {
		t.Fatalf("read initial commit: %v", err)
	}
	external, err := CreateCommit(t.Context(), repo, initialCommit.TreeHash, initial, "external", "Test", "test@example.com")
	if err != nil {
		t.Fatalf("create external commit: %v", err)
	}

	var advanceOnce sync.Once
	ctx := withBeforeRefCAS(t.Context(), func() {
		advanceOnce.Do(func() {
			if err := CompareAndSwapRef(context.Background(), repo, first, external, initial); err != nil {
				t.Errorf("advance first ref: %v", err)
			}
		})
	})
	var losing []plumbing.Hash
	calls := 0
	err = runPersistentRefTransactions(ctx, repo, []plumbing.ReferenceName{second, first}, func(current map[plumbing.ReferenceName]plumbing.Hash) (map[plumbing.ReferenceName]plumbing.Hash, bool, error) {
		calls++
		next := make(map[plumbing.ReferenceName]plumbing.Hash, 2)
		for _, refName := range []plumbing.ReferenceName{first, second} {
			parent, err := repo.CommitObject(current[refName])
			if err != nil {
				return nil, false, err
			}
			commitHash, err := CreateCommit(t.Context(), repo, parent.TreeHash, current[refName], fmt.Sprintf("%s-attempt-%d", refName, calls), "Test", "test@example.com")
			if err != nil {
				return nil, false, err
			}
			next[refName] = commitHash
			if calls == 1 {
				losing = append(losing, commitHash)
			}
		}
		return next, true, nil
	})
	if err != nil {
		t.Fatalf("run persistent multi-ref transaction: %v", err)
	}
	if calls != 2 {
		t.Fatalf("mutation calls = %d, want 2", calls)
	}
	_, commonDir, err := repositoryDirs(t.Context(), repo)
	if err != nil {
		t.Fatalf("resolve repository directories: %v", err)
	}
	for _, hash := range losing {
		objectPath := filepath.Join(commonDir, "objects", hash.String()[:2], hash.String()[2:])
		if _, err := os.Stat(objectPath); !errors.Is(err, os.ErrNotExist) {
			t.Errorf("losing commit %s still exists: %v", hash, err)
		}
	}
}

