func newProjectGetCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "get <project>",
		Short: "Show a project by name or ULID",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
