+func TestRunPersistentRefTransaction_RebuildsAndCleansLosingCommit(t *testing.T) {
+	t.Parallel()
+	repo, initial := setupBranchTestRepo(t)
+	refName := plumbing.ReferenceName("refs/entire/checkpoints/01/rebuild-cleanup")
+	if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, initial)); err != nil {
+		t.Fatalf("initialize ref: %v", err)
+	}
+
+	var (
+		calls       int
+		losing      plumbing.Hash
+		externalTip plumbing.Hash
+	)
+	got, err := runPersistentRefTransaction(t.Context(), repo, refName, func(current plumbing.Hash) (plumbing.Hash, bool, error) {
+		calls++
+		parent, err := repo.CommitObject(current)
+		if err != nil {
+			return plumbing.ZeroHash, false, err
+		}
+		marker := fmt.Sprintf("attempt-%d", calls)
+		blob, err := CreateBlobFromContent(repo, []byte(marker))
+		if err != nil {
+			return plumbing.ZeroHash, false, err
+		}
+		tree, err := ApplyTreeChanges(t.Context(), repo, parent.TreeHash, []TreeChange{{
+			Path:  "cas-marker.txt",
+			Entry: &object.TreeEntry{Name: "cas-marker.txt", Mode: filemode.Regular, Hash: blob},
+		}})
+		if err != nil {
+			return plumbing.ZeroHash, false, err
+		}
+		newCommit, err := CreateCommit(t.Context(), repo, tree, current, marker, "Test", "test@example.com")
+		if err != nil {
+			return plumbing.ZeroHash, false, err
+		}
+		if calls == 1 {
+			losing = newCommit
+			externalTip, err = CreateCommit(t.Context(), repo, parent.TreeHash, current, "external writer", "Test", "test@example.com")
+			if err != nil {
+				return plumbing.ZeroHash, false, err
+			}
+			if err := CompareAndSwapRef(context.Background(), repo, refName, externalTip, current); err != nil {
+				return plumbing.ZeroHash, false, err
+			}
+		}
+		return newCommit, true, nil
+	})
+	if err != nil {
+		t.Fatalf("run persistent ref transaction: %v", err)
+	}
+	if calls != 2 {
+		t.Fatalf("mutation calls = %d, want 2", calls)
+	}
+	finalCommit, err := repo.CommitObject(got)
+	if err != nil {
+		t.Fatalf("read final commit: %v", err)
+	}
+	if len(finalCommit.ParentHashes) != 1 || finalCommit.ParentHashes[0] != externalTip {
+		t.Fatalf("final parents = %v, want [%s]", finalCommit.ParentHashes, externalTip)
+	}
+	finalTree, err := finalCommit.Tree()
+	if err != nil {
+		t.Fatalf("read final tree: %v", err)
+	}
+	file, err := finalTree.File("cas-marker.txt")
+	if err != nil {
+		t.Fatalf("read marker: %v", err)
+	}
+	contents, err := file.Contents()
+	if err != nil {
+		t.Fatalf("read marker contents: %v", err)
+	}
+	if contents != "attempt-2" {
+		t.Fatalf("marker = %q, want attempt-2", contents)
+	}
+	commonDir, err := resolveGitCommonDir(t.Context(), repo)
+	if err != nil {
+		t.Fatalf("resolve git common dir: %v", err)
+	}
+	objectPath := filepath.Join(commonDir, "objects", losing.String()[:2], losing.String()[2:])
+	if _, err := os.Stat(objectPath); !errors.Is(err, os.ErrNotExist) {
+		t.Fatalf("losing commit %s still exists: %v", losing, err)
+	}
