package checkpoint

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"

	"github.com/go-git/go-git/v6/plumbing"
)

func persistentRefLockPath(commonDir string, refName plumbing.ReferenceName) (string, error) {
	lockDir := filepath.Join(commonDir, "entire-persistent-ref-locks")
	if err := os.MkdirAll(lockDir, 0o750); err != nil {
		return "", fmt.Errorf("create persistent ref lock directory: %w", err)
	}
	safe := strings.NewReplacer("/", "_", "\\", "_", ":", "_").Replace(refName.String())
	return filepath.Join(lockDir, safe+".lock"), nil
}

func withPersistentRefFlock(ctx context.Context, commonDir string, refName plumbing.ReferenceName, fn func() error) error {
	path, err := persistentRefLockPath(commonDir, refName)
	if err != nil {
		return err
	}
	release, err := flock.AcquireContext(ctx, path)
	if err != nil {
		return fmt.Errorf("acquire persistent ref flock %s: %w", refName, err)
	}
	defer release()
	return fn()
}

func withPersistentRefFlocks(ctx context.Context, commonDir string, refNames []plumbing.ReferenceName, fn func() error) error {
	// Every writer takes multiple ref locks in the same order to prevent deadlock.
	ordered := append([]plumbing.ReferenceName(nil), refNames...)
	sort.Slice(ordered, func(i, j int) bool { return ordered[i] < ordered[j] })
	unique := ordered[:0]
	for _, refName := range ordered {
		if len(unique) == 0 || unique[len(unique)-1] != refName {
			unique = append(unique, refName)
		}
	}

	var acquire func(int) error
	acquire = func(index int) error {
		if index == len(unique) {
			return fn()
		}
		return withPersistentRefFlock(ctx, commonDir, unique[index], func() error {
			return acquire(index + 1)
		})
	}
	return acquire(0)
}
type MultiRefMutation func(current map[plumbing.ReferenceName]plumbing.Hash) (next map[plumbing.ReferenceName]plumbing.Hash, changed bool, err error)

type beforeRefCASKey struct{}

func withBeforeRefCAS(ctx context.Context, hook func()) context.Context {
	return context.WithValue(ctx, beforeRefCASKey{}, hook)
}

// RunRefTransaction retries a logical ref mutation against the latest tip.
// The callback is invoked again after every CAS conflict, so it must rebuild
// trees and commits from current rather than reuse objects based on a stale tip.
func RunRefTransaction(
	ctx context.Context,
	repo *git.Repository,
	refName plumbing.ReferenceName,
	mutate RefMutation,
) (plumbing.Hash, error) {
	return runRefTransaction(ctx, repo, refName, mutate, false)
}

// runPersistentRefTransaction removes targets from losing attempts, so mutate
// must return commits constructed for this transaction rather than shared ones.
func runPersistentRefTransaction(
	ctx context.Context,
	repo *git.Repository,
	refName plumbing.ReferenceName,
	mutate RefMutation,
) (plumbing.Hash, error) {
	return runRefTransaction(ctx, repo, refName, mutate, true)
}

func runRefTransaction(
	ctx context.Context,
	repo *git.Repository,
	refName plumbing.ReferenceName,
	mutate RefMutation,
	cleanupConflicts bool,
) (plumbing.Hash, error) {
	commonDir, err := resolveGitCommonDir(ctx, repo)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	var result plumbing.Hash
	err = withPersistentRefFlock(ctx, commonDir, refName, func() error {
		for attempt := range refTransactionMaxAttempts {
			if err := ctx.Err(); err != nil {
				return err //nolint:wrapcheck // canonical context cancellation
			}

			current, err := ReadRefHash(repo, refName)
			if err != nil {
				return err
			}
			var next plumbing.Hash
			var changed bool
			objectLock := repositoryObjectLock(repo)
			func() {
				objectLock.Lock()
				defer objectLock.Unlock()
				next, changed, err = mutate(current)
			}()
			if err != nil {
				return err
			}
			if !changed {
				result = current
				return nil
			}
			if next.IsZero() {
				return fmt.Errorf("ref transaction %s produced an empty target", refName)
			}

			if hook, ok := ctx.Value(beforeRefCASKey{}).(func()); ok {
				hook()
			}
			err = CompareAndSwapRef(ctx, repo, refName, next, current)
			if err == nil {
				result = next
				return nil
			}
			if !errors.Is(err, ErrRefConflict) {
				return err
			}
			if cleanupConflicts && next != current {
				tryDeleteLooseObject(commonDir, next)
			}
			if attempt+1 == refTransactionMaxAttempts {
				return fmt.Errorf("update ref %s after %d attempts: %w", refName, refTransactionMaxAttempts, err)
			}
			if err := refTransactionBackoff(ctx, attempt); err != nil {
				return err
			}
		}
		panic("unreachable")
	})
	return result, err
}

// RunRefTransactions retries a logical mutation that publishes several refs
// atomically. The callback is invoked again after every CAS conflict, so it
// must rebuild all affected objects from the current tips.
func RunRefTransactions(
	ctx context.Context,
	repo *git.Repository,
	refNames []plumbing.ReferenceName,
	mutate MultiRefMutation,
) error {
	return runRefTransactions(ctx, repo, refNames, mutate, false)
}

// runPersistentRefTransactions removes targets from losing attempts, so mutate
// must return commits constructed for this transaction rather than shared ones.
func runPersistentRefTransactions(
	ctx context.Context,
	repo *git.Repository,
	refNames []plumbing.ReferenceName,
	mutate MultiRefMutation,
) error {
	return runRefTransactions(ctx, repo, refNames, mutate, true)
}

func runRefTransactions(
	ctx context.Context,
	repo *git.Repository,
	refNames []plumbing.ReferenceName,
	mutate MultiRefMutation,
	cleanupConflicts bool,
) error {
	if len(refNames) == 0 {
		return errors.New("multi-ref transaction: at least one ref is required")
	}
	ordered := append([]plumbing.ReferenceName(nil), refNames...)
	sort.Slice(ordered, func(i, j int) bool { return ordered[i] < ordered[j] })
	for i := 1; i < len(ordered); i++ {
		if ordered[i] == ordered[i-1] {
			return fmt.Errorf("multi-ref transaction: duplicate ref %s", ordered[i])
		}
	}

	commonDir, err := resolveGitCommonDir(ctx, repo)
	if err != nil {
		return err
	}

	return withPersistentRefFlocks(ctx, commonDir, ordered, func() error {
		for attempt := range refTransactionMaxAttempts {
			if err := ctx.Err(); err != nil {
				return err //nolint:wrapcheck // canonical context cancellation
			}
			current := make(map[plumbing.ReferenceName]plumbing.Hash, len(ordered))
			for _, refName := range ordered {
				refHash, err := ReadRefHash(repo, refName)
				if err != nil {
					return err
				}
				current[refName] = refHash
			}

			var next map[plumbing.ReferenceName]plumbing.Hash
			var changed bool
			var err error
			objectLock := repositoryObjectLock(repo)
			func() {
				objectLock.Lock()
				defer objectLock.Unlock()
				next, changed, err = mutate(current)
			}()
			if err != nil {
				return err
			}
			if !changed {
				return nil
			}

			updates := make([]RefUpdate, 0, len(ordered))
			for _, refName := range ordered {
				newHash, ok := next[refName]
				if !ok || newHash.IsZero() {
					return fmt.Errorf("multi-ref transaction %s produced an empty target", refName)
				}
				updates = append(updates, RefUpdate{Ref: refName, New: newHash, Expected: current[refName]})
			}
			if err := CompareAndSwapRefs(ctx, repo, updates); err == nil {
				return nil
			} else if !errors.Is(err, ErrRefConflict) {
				return err
			}
			if cleanupConflicts {
				cleanupLosingRefUpdates(commonDir, updates)
			}
			if attempt+1 == refTransactionMaxAttempts {
				return fmt.Errorf("update %d refs after %d attempts: %w", len(ordered), refTransactionMaxAttempts, ErrRefConflict)
			}
			if err := refTransactionBackoff(ctx, attempt); err != nil {
				return err
			}
		}
		panic("unreachable")
	})
}

func cleanupLosingRefUpdates(commonDir string, updates []RefUpdate) {
	cleaned := make(map[plumbing.Hash]struct{}, len(updates))
	for _, update := range updates {
		if update.New == update.Expected {
			continue
		}
		if _, ok := cleaned[update.New]; ok {
			continue
		}
		tryDeleteLooseObject(commonDir, update.New)
		cleaned[update.New] = struct{}{}
	}
}

// ReadRefHash returns a ref's current hash, or ZeroHash when it does not exist.
func ReadRefHash(repo *git.Repository, refName plumbing.ReferenceName) (plumbing.Hash, error) {
	ref, err := repo.Reference(refName, true)
	if errors.Is(err, plumbing.ErrReferenceNotFound) {
		return plumbing.ZeroHash, nil
	}
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read ref %s: %w", refName, err)
	}
	return ref.Hash(), nil
}

// CompareAndSwapRef atomically updates refName through native Git. expected
// ZeroHash means the ref must not exist. Native Git is the lock interoperability
// boundary across hooks, worktrees, and other Git clients.
func CompareAndSwapRef(
	ctx context.Context,
	repo *git.Repository,
	refName plumbing.ReferenceName,
	newHash, expected plumbing.Hash,
) error {
	return CompareAndSwapRefs(ctx, repo, []RefUpdate{{Ref: refName, New: newHash, Expected: expected}})
}

