// TestCommitHookPerformance compares a control commit with a commit whose
// Entire hooks process a realistic set of session states.
//
// Run: go test -v -run TestCommitHookPerformance -tags hookperf -timeout 15m ./cmd/entire/cli/strategy/
func TestCommitHookPerformance(t *testing.T) {
	cacheDir := cloneSourceRepo(t)
	scenarios := []struct {
		name   string
		ended  int
		idle   int
		active int
	}{
		{"100sessions", 88, 11, 1},
		{"200sessions", 176, 22, 2},
		{"500sessions", 440, 55, 5},
	}

	type result struct {
		name            string
		total           int
		control         time.Duration
		prepare         time.Duration
		postCommit      time.Duration
		processSessions time.Duration
		storageWrite    time.Duration
	}
	results := make([]result, 0, len(scenarios))

	for _, sc := range scenarios {
		t.Run(sc.name, func(t *testing.T) {
			totalSessions := sc.ended + sc.idle + sc.active
			dir := localClone(t, cacheDir)
			t.Chdir(dir)
			paths.ClearWorktreeRootCache()
			session.ClearGitCommonDirCache()

			seedBranches(t, dir, 200)
			controlDur := timeControlCommit(t, dir)
			gitRun(t, dir, "reset", "HEAD~1")
			gitRun(t, dir, "add", "perf_control.txt")
			createHookPerfSettings(t, dir)

			baseCommits := collectBaseCommits(t, dir, totalSessions)
			fixture := seedHookPerfSessions(t, dir, baseCommits, sc.ended, sc.idle, sc.active)
			gitRun(t, dir, "pack-refs", "--all")
			assertHookPerfFixture(t, dir, fixture, totalSessions)

			t.Setenv("ENTIRE_TEST_TTY", "1")
			paths.ClearWorktreeRootCache()
			session.ClearGitCommonDirCache()
			commitMsgFile := filepath.Join(dir, ".git", "COMMIT_EDITMSG")
			if err := os.WriteFile(commitMsgFile, []byte("implement feature\n"), 0o644); err != nil {
				t.Fatalf("write commit msg: %v", err)
			}

			prepStart := time.Now()
			if err := (&ManualCommitStrategy{}).PrepareCommitMsg(context.Background(), commitMsgFile, "message"); err != nil {
				t.Fatalf("PrepareCommitMsg: %v", err)
			}
			prepDur := time.Since(prepStart)

			msgBytes, err := os.ReadFile(commitMsgFile)
			if err != nil {
				t.Fatalf("read commit msg: %v", err)
			}
			commitMsg := string(msgBytes)
			if _, found := trailers.ParseCheckpoint(commitMsg); !found {
				cpID, err := id.Generate()
				if err != nil {
					t.Fatalf("generate checkpoint ID: %v", err)
				}
				commitMsg = fmt.Sprintf("%s\n%s: %s\n", strings.TrimRight(commitMsg, "\n"), trailers.CheckpointTrailerKey, cpID)
				t.Log("Injected trailer because PrepareCommitMsg skipped content-aware linking")
			}
			gitRun(t, dir, "commit", "-m", commitMsg)

			paths.ClearWorktreeRootCache()
			session.ClearGitCommonDirCache()
			logger, err := logging.New(logging.Config{Dir: filepath.Join(dir, logging.LogsDir), Level: slog.LevelDebug})
			if err != nil {
				t.Fatalf("create performance logger: %v", err)
			}
			postStart := time.Now()
			postErr := (&ManualCommitStrategy{}).PostCommit(logging.WithLogger(context.Background(), logger))
			postDur := time.Since(postStart)
			if err := logger.Close(); err != nil {
				t.Fatalf("close performance logger: %v", err)
			}
			if postErr != nil {
				t.Fatalf("PostCommit: %v", postErr)
			}

			checkpointID, found := trailers.ParseCheckpoint(commitMsg)
			if !found {
				t.Fatal("committed message has no checkpoint trailer")
			}
			assertHookPerfCondensed(t, dir, fixture, checkpointID)
			timings := readHookPerfTimings(t, dir)
			overhead := maxDuration(prepDur+postDur-controlDur, 0)

			t.Logf("=== %s ===", sc.name)
			t.Logf("  Sessions:         %d (ended=%d, idle=%d, active=%d)", totalSessions, sc.ended, sc.idle, sc.active)
			t.Logf("  Base commits:     %d unique", len(baseCommits))
			t.Logf("  Control commit:   %s", controlDur.Round(time.Millisecond))
			t.Logf("  PrepareCommitMsg: %s", prepDur.Round(time.Millisecond))
			t.Logf("  PostCommit:       %s", postDur.Round(time.Millisecond))
			t.Logf("  Find sessions:    %s", timings.findSessions)
			t.Logf("  Process sessions: %s", timings.processSessions)
			t.Logf("  Condensations:    %d", timings.condensations)
			t.Logf("    Extract:        %s", timings.extract)
			t.Logf("    Attribution:    %s", timings.attribution)
			t.Logf("    Redaction:      %s", timings.redaction)
			t.Logf("    Storage write:  %s", timings.write)
			t.Logf("    Condense total: %s", timings.condenseTotal)
			t.Logf("  TOTAL HOOKS:      %s", (prepDur + postDur).Round(time.Millisecond))
			t.Logf("  OVERHEAD:         %s", overhead.Round(time.Millisecond))

			results = append(results, result{
				name: sc.name, total: totalSessions, control: controlDur, prepare: prepDur,
				postCommit: postDur, processSessions: timings.processSessions, storageWrite: timings.write,
			})
		})
	}

	t.Log("")
	t.Log("========== COMMIT HOOK PERFORMANCE ==========")
	t.Logf("%-14s | %8s | %10s | %10s | %12s | %12s | %12s | %12s | %10s",
		"Scenario", "Sessions", "Control", "Prepare", "PostCommit", "Process", "StoreWrite", "Total+Hooks", "Overhead")
	t.Log(strings.Repeat("-", 132))
	for _, r := range results {
		total := r.prepare + r.postCommit
		overhead := maxDuration(total-r.control, 0)
		t.Logf("%-14s | %8d | %10s | %10s | %12s | %12s | %12s | %12s | %10s",
			r.name, r.total, r.control.Round(time.Millisecond), r.prepare.Round(time.Millisecond),
			r.postCommit.Round(time.Millisecond), r.processSessions.Round(time.Millisecond),
			r.storageWrite.Round(time.Millisecond), total.Round(time.Millisecond), overhead.Round(time.Millisecond))
	}
}

func maxDuration(value, floor time.Duration) time.Duration {
	if value < floor {
		return floor
	}
	return value
}

